-- Any hotspot this run no longer claims is removed, so a regenerated file is
-- authoritative rather than merely additive. environmental_events.hotspot_id is
-- ON DELETE SET NULL, so an event outlives a retired hotspot.
DELETE FROM hotspots WHERE id NOT IN ('HS-CN-PRD', 'HS-CN-SHANGHAI', 'HS-CN-XIAMEN', 'HS-HK-HARBOUR', 'HS-HK-NT', 'HS-ID-JAKARTA', 'HS-ID-NJAKARTA', 'HS-ID-SEMARANG', 'HS-ID-SURABAYA', 'HS-MY-JOHOR', 'HS-MY-KLANG', 'HS-SG-CENTRAL', 'HS-SG-EASTCOAST', 'HS-SG-MARINA', 'HS-SG-NORTH', 'HS-SG-SOUTHWEST');

-- The count AC-15 and plan S19 rest on.
DO $$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM hotspots;
  IF n <> 16 THEN
    RAISE EXCEPTION '05_regional.sql expected 16 hotspots, found %', n;
  END IF;
END $$;

